import unittest
from candidate import sort_even

class TestSortEvenIndices(unittest.TestCase):
    def test_normal_case_even_length(self):
        self.assertEqual(sort_even([1, 2, 3, 4]), [1, 2, 3, 4])

    def test_normal_case_odd_length(self):
        self.assertEqual(sort_even([5, 6, 3, 4, 7]), [3, 6, 5, 4, 7])

    def test_empty_list(self):
        self.assertEqual(sort_even([]), [])

    def test_single_element(self):
        self.assertEqual(sort_even([42]), [42])

    def test_single_even_element(self):
        self.assertEqual(sort_even([10]), [10])

    def test_single_odd_element(self):
        self.assertEqual(sort_even([1]), [1])

    def test_all_odd_indices_same(self):
        self.assertEqual(sort_even([1, 1, 1, 1]), [1, 1, 1, 1])

    def test_all_even_indices_same(self):
        self.assertEqual(sort_even([1, 2, 2, 2]), [1, 2, 2, 2])

    def test_mixed_numbers(self):
        self.assertEqual(sort_even([-3, 2, 7, -1]), [-3, 2, -1, 7])

    def test_floats(self):
        self.assertAlmostEqual(sort_even([1.5, 2.5, 3.5, 4.5]), [1.5, 2.5, 3.5, 4.5])
        self.assertAlmostEqual(sort_even([1.5, 2.5, 3.5]), [1.5, 2.5, 3.5])

    def test_mixed_types(self):
        with self.assertRaises(TypeError):
            sort_even([1, 'a', 3])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            sort_even(None)

    def test_non_list_input(self):
        with self.assertRaises(TypeError):
            sort_even("not a list")

    def test_odd_length_mismatch(self):
        self.assertEqual(sort_even([1, 2, 3, 4, 5, 6]), [1, 2, 3, 4, 5, 6])

    def test_odd_indices_preserved(self):
        self.assertEqual(sort_even([10, 20, 30, 40, 50]), [10, 20, 30, 40, 50])

    def test_sorted_even_indices(self):
        self.assertEqual(sort_even([3, 1, 2, 4]), [1, 3, 2, 4])

    def test_large_list(self):
        large_list = list(range(100))
        expected = list(range(0, 100, 2))
        expected.sort()
        result = sort_even(large_list)
        self.assertEqual(result[:len(expected)], expected)
        self.assertEqual(result[len(expected):], large_list[1::2])
